import type { PersonId } from "./Identity.ts";
import type { MembershipRole, TeamId } from "./Team.ts";

export interface Actor {
  readonly personId: PersonId;
  readonly organizationAdmin: boolean;

  readonly roles: ReadonlyMap<TeamId, MembershipRole>;
}

export type OrganizationAction =
  | "organization.viewSettings"
  | "organization.updateSettings"
  | "organization.setAdmin"
  | "organization.removePerson"
  | "organization.listTeams"
  | "organization.createTeam";

export type TeamAction =
  | "team.view"
  | "team.update"
  | "team.viewRoster"
  | "team.addMember"
  | "team.removeMember"
  | "team.assignLead"
  | "team.removeLead"
  | "team.viewResults"
  | "team.viewPulses"
  | "team.createPulse"
  | "team.editPulse"
  | "team.viewRounds"
  | "team.manageRounds"
  | "team.viewActions"
  | "team.createAction"
  | "team.updateAction"
  | "team.viewNote"
  | "team.writeNote";

export type Action = OrganizationAction | TeamAction;

export type Resource = { readonly _tag: "Organization" } | { readonly _tag: "Team"; readonly teamId: TeamId };

export type ResourceOf<A extends Action> = A extends TeamAction
  ? Extract<Resource, { readonly _tag: "Team" }>
  : Extract<Resource, { readonly _tag: "Organization" }>;

type Grantee = "admin" | MembershipRole;

export const PERMISSIONS: Readonly<Record<Action, readonly Grantee[]>> = {
  "organization.viewSettings": ["admin"],
  "organization.updateSettings": ["admin"],
  "organization.setAdmin": ["admin"],
  "organization.removePerson": ["admin"],
  "organization.listTeams": ["admin"],
  "organization.createTeam": ["admin"],
  "team.view": ["admin", "lead", "member", "viewer"],
  "team.update": ["admin"],
  "team.viewRoster": ["admin", "lead"],
  "team.addMember": ["admin", "lead"],
  "team.removeMember": ["admin", "lead"],
  "team.assignLead": ["admin"],
  "team.removeLead": ["admin"],
  "team.viewResults": ["lead", "member", "viewer"],

  "team.viewPulses": ["admin", "lead"],
  "team.createPulse": ["admin", "lead"],
  "team.editPulse": ["admin", "lead"],
  "team.viewRounds": ["admin", "lead"],
  "team.manageRounds": ["admin", "lead"],

  "team.viewActions": ["lead", "member", "viewer"],
  "team.createAction": ["lead"],
  "team.updateAction": ["lead"],

  "team.viewNote": ["lead", "member", "viewer"],
  "team.writeNote": ["lead"],
};

export const can = <A extends Action>(actor: Actor, action: A, resource: ResourceOf<A>): boolean => {
  const grantees = PERMISSIONS[action];

  if (actor.organizationAdmin && grantees.includes("admin")) {
    return true;
  }

  if (resource._tag !== "Team") {
    return false;
  }

  const role = actor.roles.get(resource.teamId);

  return role !== undefined && grantees.includes(role);
};
import { Context } from "effect";
import type { Effect, Option, Redacted } from "effect";
import type { Identity, SessionId } from "./Identity.ts";
import type { OrganizationId } from "./Organization.ts";
import type { AuthUnavailable, Unauthenticated } from "./SignIn.ts";

export interface SignedInSession {
  readonly identity: Identity;
  readonly sessionId: SessionId;
}

export interface SessionIdentityProviderShape {
  readonly authenticate: (
    cookie: Redacted.Redacted,
  ) => Effect.Effect<SignedInSession, Unauthenticated | AuthUnavailable>;

  readonly chosenOrganization: (
    sessionId: SessionId,
  ) => Effect.Effect<Option.Option<OrganizationId>, AuthUnavailable>;

  readonly chooseOrganization: (
    sessionId: SessionId,
    organizationId: OrganizationId,
  ) => Effect.Effect<void, AuthUnavailable>;

  readonly sendSignInCode: (email: string) => Effect.Effect<void, AuthUnavailable>;

  readonly verifySignInCode: (
    email: string,
    code: string,
  ) => Effect.Effect<Option.Option<string>, AuthUnavailable>;

  readonly revokeSession: (sessionId: SessionId) => Effect.Effect<void, AuthUnavailable>;
}

export class SessionIdentityProvider extends Context.Service<
  SessionIdentityProvider,
  SessionIdentityProviderShape
>()("@surveybeat/domain/SessionIdentityProvider") {}
import { SESSION_COOKIE } from "@surveybeat/auth";
import {
  AuthUnavailable,
  AuthUserId,
  identityOf,
  SessionId,
  SessionIdentityProvider,
  Unauthenticated,
} from "@surveybeat/domain";
import type { OrganizationId } from "@surveybeat/domain";
import type { Auth } from "better-auth";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Redacted from "effect/Redacted";

const authOrigin = "http://localhost:5173";

const authRequest = (path: string, body: unknown) =>
  new Request(`${authOrigin}${path}`, {
    method: "POST",
    headers: { "content-type": "application/json", origin: authOrigin },
    body: JSON.stringify(body),
  });

const sessionTokenFromCookie = (header: string): string => {
  const pair = header.split(";")[0] ?? "";

  return Option.getOrElse(Option.fromNullishOr(pair.split("=").slice(1).join("=")), () => "");
};

export const betterAuthIdentityProvider = (params: {
  readonly auth: Pick<Auth, "api" | "handler">;
  readonly chosenOrganization: (
    sessionId: SessionId,
  ) => Effect.Effect<Option.Option<OrganizationId>, AuthUnavailable>;
  readonly rememberOrganization: (
    sessionId: SessionId,
    organizationId: OrganizationId,
  ) => Effect.Effect<void, AuthUnavailable>;
  readonly deleteSession: (sessionId: SessionId) => Effect.Effect<void, AuthUnavailable>;
}) =>
  SessionIdentityProvider.of({
    authenticate: (cookie) =>
      Effect.tryPromise({
        try: () =>
          params.auth.api.getSession({
            headers: new Headers({ cookie: `${SESSION_COOKIE}=${Redacted.value(cookie)}` }),
          }),
        catch: () => new AuthUnavailable(),
      }).pipe(
        Effect.flatMap((session) =>
          session === null
            ? Effect.fail(new Unauthenticated())
            : Effect.succeed({
                identity: identityOf(
                  AuthUserId.make(session.user.id),
                  session.user.email,
                  session.user.emailVerified,
                ),
                sessionId: SessionId.make(session.session.id),
              }),
        ),
      ),

    chosenOrganization: (sessionId) => params.chosenOrganization(sessionId),

    chooseOrganization: (sessionId, organizationId) => params.rememberOrganization(sessionId, organizationId),

    sendSignInCode: (email) =>
      Effect.tryPromise({
        try: () =>
          params.auth
            .handler(authRequest("/auth/email-otp/send-verification-otp", { email, type: "sign-in" }))
            .then((response) => {
              if (!response.ok) {
                throw new Error(`send-verification-otp answered ${response.status}`);
              }

              return response;
            }),
        catch: () => new AuthUnavailable(),
      }).pipe(Effect.asVoid),

    verifySignInCode: (email, code) =>
      Effect.tryPromise({
        try: () =>
          params.auth
            .handler(authRequest("/auth/sign-in/email-otp", { email, otp: code }))
            .then((response) =>
              response.ok
                ? Option.map(Option.fromNullishOr(response.headers.get("set-cookie")), sessionTokenFromCookie)
                : Option.none<string>(),
            ),
        catch: () => new AuthUnavailable(),
      }),

    revokeSession: (sessionId) => params.deleteSession(sessionId),
  });
import type { CodeDelivery } from "@surveybeat/auth";
import { EmailAddress, Policy } from "@surveybeat/domain";
import type { EmailAccepted, EmailOutcomeUnknown, EmailRejected, OutgoingEmail } from "@surveybeat/domain";
